function catalogView(query=''){
 const q=query.trim().toLowerCase(),filtered=contexts.filter(c=>c.join(' ').toLowerCase().includes(q)),results=q?airportTerms.filter(x=>`${x.term} ${x.meaning} ${x.stage}`.toLowerCase().includes(q)).slice(0,8):[]
 const cards=filtered.length?filtered.map((c,i)=>`<a class="catalog-card" href="${c[3]}"><span class="card-number">${String(i+1).padStart(2,'0')}</span><span class="card-title">${c[0]}</span><span class="card-meta">${c[1]} usos contextuales</span><span class="card-footer"><span class="card-level">${c[2]}</span><span class="pdf-mark">ABRIR →</span></span></a>`).join(''):'<div class="empty">No encontramos un grupo con ese término. <a href="/herramientas/vocabulario/ingles/phrasal-verbs/explorar">Busca en el banco completo.</a></div>'
 const found=results.length?`<section class="search-results"><div class="section-head"><div><span class="section-index">RESULTADOS</span><h2>Expresiones relacionadas</h2></div></div><div class="result-row">${results.map(x=>`<button class="result-chip" data-term="${x.term}"><strong>${x.term}</strong><span>${x.meaning}</span></button>`).join('')}</div></section>`:''
 return shell(`<section class="catalog-hero"><div><p class="eyebrow">Herramientas · Inglés</p><h1 class="display">Banco de phrasal verbs</h1><p class="lede">Una sola biblioteca. Distintas formas de aprenderla: contexto, profesión, verbo y partícula.</p><div class="actions"><a class="btn red link-btn" href="/herramientas/vocabulario/ingles/phrasal-verbs/explorar">Explorar los 672 usos</a></div></div><div class="search-panel"><label class="search-label" for="catalog-search">Filtrar las rutas principales</label><div class="search-wrap"><input id="catalog-search" class="search-input" value="${esc(query)}" placeholder="Viajes, logística, derecho…"><span class="search-key">⌘ K</span></div><a href="/herramientas/vocabulario/ingles/phrasal-verbs/explorar">Buscar expresiones en todo el banco →</a></div></section><section class="stats"><div class="stat"><strong>334</strong><span>expresiones únicas</span></div><div class="stat"><strong>672</strong><span>significados y usos</span></div><div class="stat"><strong>40</strong><span>rutas amplias</span></div><div class="stat"><strong>1344</strong><span>ejemplos contextualizados</span></div></section>${found}${visualHub()}<section><div class="section-head"><div><span class="section-index">01 / CONTEXTOS</span><h2>Aprende dentro de una situación</h2></div><p>Cada grupo incluye subtemas, ejemplos, trazabilidad y práctica transversal.</p></div><div class="context-grid">${cards}</div></section><section class="duo-grid"><div><div class="section-head"><div><span class="section-index">02 / VERBOS</span><h2>Compara una familia</h2></div></div><div class="index-panel">${verbs.map(v=>`<a class="index-row" href="${v[3]}"><span class="index-code">${v[0]}</span><span class="index-detail">${v[1]} formas · ${v[2]} significados</span><span>→</span></a>`).join('')}</div></div><div><div class="section-head"><div><span class="section-index">03 / PARTÍCULAS</span><h2>Entiende patrones</h2></div></div><div class="index-panel">${particles.map(p=>`<a class="index-row" href="${p[3]}"><span class="index-code">${p[0]}</span><span class="index-detail">${p[1]} formas · ${p[2]} significados</span><span>→</span></a>`).join('')}</div></div></section>`,'catalog')}

function airportView(){
 const known=mastered(),progress=airportTerms.filter(x=>known.has(x.term)).length
 const stages=stageOrder.map(([num,title])=>{const terms=airportTerms.filter(x=>x.stage===title);return `<article class="stage"><div class="stage-top"><span class="stage-num">${num}</span><span class="stage-count">${terms.length} expresiones</span></div><h3>${title}</h3><div class="term-list">${terms.map(x=>`<button class="term-chip ${known.has(x.term)?'is-mastered':''}" data-term="${x.term}"><span><strong>${x.term}</strong><em>${x.meaning}</em></span><span class="term-state">${known.has(x.term)?'✓':'→'}</span></button>`).join('')}</div></article>`}).join('')
 return shell(`${crumb([['catalog','Banco'],['airport','Aeropuerto y vuelos']])}<section class="detail-hero"><div><p class="eyebrow">Contexto · Viajes</p><h1 class="display">Aeropuerto y vuelos</h1><p class="lede">Desde que sales de casa hasta que recuperas tu equipaje. Abre cada expresión para ver dos ejemplos reales.</p><div class="metric-line"><span>18 expresiones</span><span>36 ejemplos</span><span>A2–B1</span><span>9 páginas</span></div><div class="actions"><a class="btn red link-btn" href="/herramientas/vocabulario/ingles/phrasal-verbs/pdfs/phrasal-verbs-aeropuerto.pdf" download>Descargar PDF</a><button class="btn ghost" data-scroll="practice">Practicar</button></div></div><aside class="side-note"><div><span class="big">${progress}/18</span><p>Expresiones marcadas como dominadas en este dispositivo.</p><div class="progress-track"><span style="width:${Math.round(progress/18*100)}%"></span></div></div><span class="pdf-mark">PDF REAL · 9 PÁGINAS</span></aside></section><section><div class="section-head"><div><span class="section-index">RECORRIDO</span><h2>Cuatro momentos, dieciocho expresiones</h2></div><p>Cada ficha incluye significado, estructura y dos ejemplos situacionales con traducción.</p></div><div class="stage-grid">${stages}</div></section>${practiceBlock()}<div class="principle"><strong>Sistema visual:</strong> fotografía editorial para la portada; diagramas para etapas; tipografía y contexto para las fichas.</div>`,'airport')}
function practiceBlock(){quizState={index:0,score:0,answers:[]};return `<section id="practice" class="practice-panel"><div class="practice-copy"><p class="eyebrow">Evaluación equilibrada · 12 preguntas</p><h2>Reconoce, construye y corrige</h2><p>Tres preguntas por etapa. Combina selección, gramática y producción escrita; los distractores pertenecen al mismo contexto.</p><div class="quiz-balance"><span>4 etapas</span><span>3 habilidades</span><span>Resultado final</span></div></div><div class="practice-card" data-quiz-index="0">${questionMarkup(quizQuestions[0],0)}</div></section>`}
function questionMarkup(q,index){const task=q.kind==='choice'?`<div class="quiz-options">${q.options.map(o=>`<button class="quiz-option" data-airport-answer="${esc(o)}">${o}</button>`).join('')}</div>`:`<form class="quiz-input-row" data-quiz-form><label for="quiz-input">Escribe el phrasal verb</label><div><input id="quiz-input" autocomplete="off" placeholder="Tu respuesta"><button type="submit" class="btn red">Comprobar</button></div></form>`;return `<span class="quiz-step">${index+1} / ${quizQuestions.length} · ${q.stage}</span><h3>${q.text}</h3>${task}<div id="airport-feedback" class="feedback"></div>`}

function upView(){const columns=upClusters.map(([title,terms])=>`<article class="meaning-column"><span class="meaning-count">${terms.length}</span><h3>${title}</h3>${terms.map(([term,meaning])=>`<button class="term-chip" data-up-term="${term}"><span><strong>${term}</strong><em>${meaning}</em></span><span class="term-state">→</span></button>`).join('')}</article>`).join('');return shell(`${crumb([['catalog','Banco'],['up','Partícula UP']])}<section class="detail-hero"><div><p class="eyebrow">Partícula · Mapa semántico</p><h1 class="display">Phrasal verbs con UP</h1><p class="lede">UP no significa siempre “arriba”. Aquí se organiza por las ideas que suele aportar.</p><div class="metric-line"><span>22 significados</span><span>44 ejemplos</span><span>A2–B2</span><span>5 patrones</span></div><div class="actions"><a class="btn red link-btn" href="/herramientas/vocabulario/ingles/phrasal-verbs/pdfs/mapa-semantico-up.pdf" download>Descargar mapa PDF</a><button class="btn ghost" data-scroll="up-map">Ver agrupaciones</button></div></div><aside class="side-note"><div><span class="big">UP</span><p>Una partícula, cinco familias de significado y ejemplos comparables.</p></div><span class="pdf-mark">PDF REAL · 9 PÁGINAS</span></aside></section><section id="up-map"><div class="section-head"><div><span class="section-index">MAPA</span><h2>Cinco ideas principales</h2></div><p>Abre cualquier término para comparar dos contextos de uso.</p></div><div class="up-grid">${columns}</div></section><div class="principle"><strong>Imágenes:</strong> este grupo usa un mapa visual sobrio. Las expresiones polisémicas reciben comparaciones adicionales.</div>`,'up')}

function getView(){return shell(`${crumb([['catalog','Banco'],['get','Verbo GET']])}<section class="detail-hero"><div><p class="eyebrow">Familia verbal</p><h1 class="display">Phrasal verbs con GET</h1><p class="lede">Doce formas seleccionadas, ordenadas por nivel y uso.</p><div class="metric-line"><span>12 formas</span><span>18 significados</span><span>A1–B2</span></div></div><aside class="side-note"><div><span class="big">GET</span><p>Movimiento, cambio, progreso y relaciones.</p></div><span class="pdf-mark">ROADMAP · PDF 09</span></aside></section><section><div class="section-head"><div><span class="section-index">ÍNDICE</span><h2>Doce formas esenciales</h2></div></div><div class="index-panel">${getEntries.map(([term,meaning,level])=>`<button class="index-row" data-route="${term==='get over'?'put-off':'get'}"><span class="index-code">${term}</span><span class="index-detail">${meaning}</span><span class="tag">${level}</span></button>`).join('')}</div></section>`)}
function putOffView(){return shell(`${crumb([['catalog','Banco'],['put-off','PUT OFF']])}<section class="word-hero"><div><p class="eyebrow">Ficha canónica · PUT</p><h1 class="wordmark">PUT<br>OFF</h1><div class="tag-line"><span class="tag">B1</span><span class="tag">separable</span><span class="tag">neutral</span><span class="tag">trabajo</span></div></div><div class="meaning-block"><strong>posponer o aplazar algo</strong><p>Retrasar una acción o evento hasta una fecha posterior.</p></div></section><section class="lesson-grid"><article class="content-card"><h2>Estructura</h2><div class="pattern">put something off<br>put it off</div><div class="error-compare" style="margin-top:10px"><div class="error-box">✕ put off it</div><div class="error-box good">✓ put it off</div></div></article><article class="content-card"><h2>Ejemplos</h2><div class="example-row"><strong>They put the meeting off until Friday.</strong><span>Aplazaron la reunión hasta el viernes.</span></div><div class="example-row"><strong>Let’s not put it off any longer.</strong><span>No lo pospongamos más.</span></div></article></section><section class="quiz"><p class="eyebrow">Práctica breve</p><h3>We decided to ___ the project until next month.</h3><div class="quiz-options"><button class="quiz-option" data-answer="correct">put off</button><button class="quiz-option" data-answer="wrong">put on</button><button class="quiz-option" data-answer="wrong">put up with</button></div><div id="quiz-feedback" class="feedback"></div></section>`,'put-off')}

function pdfView(filter='todos'){const selected=filter==='todos'?pdfs:pdfs.filter(p=>p.type===filter),buttons=[['todos','Todos'],['contexto','Contextos'],['verbo','Familias verbales'],['partícula','Partículas']];return shell(`<section class="pdf-toolbar"><div><p class="eyebrow">Biblioteca descargable</p><h1 class="display">PDFs</h1><p class="lede">Cuarenta y un recursos reales: veintiocho rutas temáticas, seis familias verbales, seis partículas y aeropuerto.</p></div><div class="filter-row">${buttons.map(([id,label])=>`<button class="filter-btn ${filter===id?'is-active':''}" data-pdf-filter="${id}">${label}</button>`).join('')}</div></section><div class="release-note"><strong>Diseñados para estudiar:</strong> fichas compactas, dos ejemplos auténticos por uso, trazabilidad, práctica de 12 preguntas y soluciones.</div><div class="pdf-grid">${selected.map(item=>`<article class="pdf-card is-ready"><span class="pdf-type">${item.type}</span><span class="availability">Disponible</span><h3>${item.title}</h3><p>${item.meta}</p><div class="actions"><a class="btn small red link-btn" href="${item.href}" download>Descargar PDF</a><button class="btn small ghost" data-preview="${item.title}">Detalles</button></div></article>`).join('')}</div>`,'pdfs')}

function openTerm(item,kind='airport'){const known=mastered(),isKnown=known.has(item.term);dialog.innerHTML=`<div class="dialog-inner term-dialog"><div class="dialog-top"><div><p class="eyebrow">${kind==='airport'?esc(item.stage):'Mapa semántico de UP'}</p><h2 id="dialog-title">${esc(item.term)}</h2></div><button class="dialog-close">×</button></div><div class="term-definition"><strong>${esc(item.meaning)}</strong><span class="tag">${esc(item.grammar||'unidad léxica')}</span></div><div class="dialog-examples">${item.examples.map(([en,es],i)=>`<article><span class="example-number">0${i+1}</span><strong>${esc(en)}</strong><p>${esc(es)}</p></article>`).join('')}</div>${kind==='airport'?`<button class="master-btn ${isKnown?'is-mastered':''}" data-toggle-mastered="${esc(item.term)}">${isKnown?'✓ Dominada':'Marcar como dominada'}</button>`:'<p class="dialog-note">Aprende la expresión completa: la partícula orienta el significado, pero no lo determina por sí sola.</p>'}</div>`;dialog.showModal();dialog.querySelector('.dialog-close').onclick=()=>dialog.close()}
function openPreview(title){const item=pdfs.find(p=>p.title===title);dialog.innerHTML=`<div class="dialog-inner"><div class="dialog-top"><div><p class="eyebrow">${item?.href?'Recurso disponible':'Recurso en roadmap'}</p><h2 id="dialog-title">${esc(title)}</h2></div><button class="dialog-close">×</button></div><div class="pdf-sheet"><div class="mini-rule"></div><h3>${esc(title)}</h3><p>${item?.meta||'Guía visual, práctica y soluciones.'}</p></div>${item?.href?`<a class="btn red link-btn dialog-download" href="${item.href}" download>Descargar PDF</a>`:'<p class="dialog-note">Esta tarjeta define el volumen previsto. La primera producción completa prioriza Aeropuerto y UP.</p>'}</div>`;dialog.showModal();dialog.querySelector('.dialog-close').onclick=()=>dialog.close()}
function updatePractice(card,index){quizState.index=index;delete card.dataset.answered;if(index>=quizQuestions.length){const pct=Math.round(quizState.score/quizQuestions.length*100);card.innerHTML=`<span class="quiz-step">Evaluación completada</span><div class="score-ring"><strong>${quizState.score}/${quizQuestions.length}</strong><span>${pct}%</span></div><h3>${pct>=80?'Buen dominio del recorrido':pct>=60?'Base sólida; revisa los errores':'Conviene volver a las fichas'}</h3><p class="dialog-note">El resultado combina reconocimiento, gramática y producción; no depende de un solo tipo de pregunta.</p><button class="btn ghost" data-restart-quiz>Repetir evaluación</button>`;return}card.dataset.quizIndex=index;card.innerHTML=questionMarkup(quizQuestions[index],index)}
function gradeAnswer(card,value){const q=quizQuestions[Number(card.dataset.quizIndex)],normalized=value.trim().toLowerCase(),accepted=(q.accepted||[q.answer]).map(x=>x.toLowerCase()),correct=accepted.includes(normalized);if(card.dataset.answered==='true')return;card.dataset.answered='true';quizState.answers.push({stage:q.stage,correct});if(correct)quizState.score+=1;card.querySelectorAll('.quiz-option').forEach(b=>{b.disabled=true;if(b.dataset.airportAnswer===q.answer)b.classList.add('is-correct')});const feedback=card.querySelector('#airport-feedback');feedback.innerHTML=`<strong>${correct?'Correcto.':'Respuesta: '+q.answer+'.'}</strong> ${q.explain} <button class="inline-next" data-next-question>Siguiente →</button>`}

function render(){const r=route();if(r==='airport')app.innerHTML=airportView();else if(r==='up')app.innerHTML=upView();else if(r==='get')app.innerHTML=getView();else if(r==='put-off')app.innerHTML=putOffView();else if(r.startsWith('pdfs/'))app.innerHTML=pdfView(r.split('/')[1]);else if(r==='pdfs')app.innerHTML=pdfView();else app.innerHTML=catalogView();scrollTo({top:0,behavior:'instant'})}
app.addEventListener('click',event=>{
 const r=event.target.closest('[data-route]');if(r)return go(r.dataset.route)
 const t=event.target.closest('[data-term]');if(t)return openTerm(airportTerms.find(x=>x.term===t.dataset.term))
 const u=event.target.closest('[data-up-term]');if(u){const [term,meaning]=upClusters.flatMap(c=>c[1]).find(x=>x[0]===u.dataset.upTerm);return openTerm({term,meaning,examples:upExamples[term]},'up')}
 const p=event.target.closest('[data-preview]');if(p)return openPreview(p.dataset.preview)
 const s=event.target.closest('[data-scroll]');if(s)return document.getElementById(s.dataset.scroll)?.scrollIntoView({behavior:'smooth'})
 const f=event.target.closest('[data-pdf-filter]');if(f)return go(`pdfs/${f.dataset.pdfFilter}`)
 const m=event.target.closest('[data-toggle-mastered]');if(m){const set=mastered();set.has(m.dataset.toggleMastered)?set.delete(m.dataset.toggleMastered):set.add(m.dataset.toggleMastered);saveMastered(set);dialog.close();render();return}
 const a=event.target.closest('[data-airport-answer]');if(a){const card=a.closest('.practice-card');if(a.dataset.airportAnswer!==quizQuestions[Number(card.dataset.quizIndex)].answer)a.classList.add('is-wrong');gradeAnswer(card,a.dataset.airportAnswer);return}
 const n=event.target.closest('[data-next-question]');if(n){const card=n.closest('.practice-card');return updatePractice(card,Number(card.dataset.quizIndex)+1)}
 const restart=event.target.closest('[data-restart-quiz]');if(restart){quizState={index:0,score:0,answers:[]};return updatePractice(restart.closest('.practice-card'),0)}
 const q=event.target.closest('[data-answer]');if(q){document.querySelectorAll('.quiz-option').forEach(b=>b.classList.remove('is-selected'));q.classList.add('is-selected');document.querySelector('#quiz-feedback').textContent=q.dataset.answer==='correct'?'Correcto. “Put off” significa posponer.':'Inténtalo otra vez: necesitas el verbo que significa “posponer”.'}
})
app.addEventListener('submit',event=>{const form=event.target.closest('[data-quiz-form]');if(!form)return;event.preventDefault();const input=form.querySelector('input');if(!input.value.trim())return;input.disabled=true;form.querySelector('button').disabled=true;gradeAnswer(form.closest('.practice-card'),input.value)})
app.addEventListener('input',event=>{if(event.target.id==='catalog-search'){app.innerHTML=catalogView(event.target.value);const input=document.querySelector('#catalog-search');input.focus();input.setSelectionRange(input.value.length,input.value.length)}})
addEventListener('keydown',event=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();document.querySelector('#catalog-search')?.focus()}})
addEventListener('hashchange',render);dialog.addEventListener('click',event=>{if(event.target===dialog)dialog.close();const m=event.target.closest('[data-toggle-mastered]');if(m){const set=mastered();set.has(m.dataset.toggleMastered)?set.delete(m.dataset.toggleMastered):set.add(m.dataset.toggleMastered);saveMastered(set);dialog.close();render()}});render()
